cat > /tmp/test-refunds.js << 'EOF'
import assert from 'node:assert/strict';
import { createTestApp, ON_ADDRESS, signUp, addProduct } from './src/lib/testing.ts';
import { markPaid } from './src/billing/service.ts';

const app = createTestApp();
const customer = signUp(app.ctx, 'buyer@example.com', { address: ON_ADDRESS });
const products = [333, 333, 333].map((price) => addProduct(app.ctx, { price }));
for (const p of products) {
  app.call('POST', '/cart/items', { token: customer.token, body: { productId: p.id, quantity: 1 } });
}
const order = app.call('POST', '/checkout', { token: customer.token, body: { addressIndex: 0 } }).body;
const invoiceId = order.invoiceId;

let invoice = app.ctx.store.invoices.require(invoiceId);
console.log('Invoice before marking paid:');
console.log('  total:', invoice.total);
console.log('  lines:', invoice.lines.map(l => ({ productId: l.productId, net: l.net, tax: l.tax })));

markPaid(app.ctx, invoiceId);

invoice = app.ctx.store.invoices.require(invoiceId);
console.log('\nInvoice after marking paid:');
console.log('  total:', invoice.total);
console.log('  lines:', invoice.lines.map(l => ({ productId: l.productId, net: l.net, tax: l.tax })));

// Test refunding
const refund = (productId) => {
  const res = app.call('POST', `/invoices/${invoiceId}/refunds`, { 
    token: signUp(app.ctx, 'admin@example.com', { admin: true }).token, 
    body: { productId } 
  });
  return res.body;
};

const amounts = products.map((p, i) => {
  const r = refund(p.id);
  console.log(`\nRefund ${i} (product ${p.id}):`, r);
  return r.amount;
});

console.log('\nFinal refund amounts:', amounts);
console.log('Total refunded:', amounts.reduce((a, b) => a + b, 0));
console.log('Invoice total:', app.ctx.store.invoices.require(invoiceId).total);
EOF
